def spec_for_value(code: int) -> ErrorCodeSpec:
    """Look an error up by its numeric code.

    Raises AmbiguousErrorCodeError for the three values upstream reuses. Prefer
    keying by constant name; this exists for decoding responses, not raising.
    """
    matches = [spec for spec in ERROR_CODES.values() if spec.code == code]
    if not matches:
        raise LookupError(f"no error code {code}")
    if len(matches) > 1:
        names = ", ".join(sorted(spec.name for spec in matches))
        raise AmbiguousErrorCodeError(f"code {code} maps to several errors: {names}")
    return matches[0]
